      'import sys\n\n\ndef main():\n    data = list(map(int, sys.stdin.read().split()))\n    n = data[0]\n    heights = data[1:1 + n] + [0]\n    stack = []\n    best = 0\n    for i, h in enumerate(heights):\n        start = i\n        while stack and stack[-1][1] >= h:\n            start, top = stack.pop()\n            best = max(best, top * (i - start))\n        stack.append((start, h))\n    print(best)\n\n\nmain()\n',
